word('se-sentir','fr:se-sentir:describe-feeling','se sentir','чувствовать себя (самоописание)','сё са(н)ти́р',3,ex('Je me sens fatigué.','Я чувствую себя уставшим.','жё мё са(н) фатигэ́'),['Чувствовать себя','Продавать','Преподавать'],0,'Нужно сказать, что вы чувствуете себя уставшим.',[('Je me sens fatigué.','жё мё са(н) фатигэ́'),('Je vends des livres.','жё ва(н) дэ ли́вр'),('J’enseigne à l’école.','жа(н)сэнь а лэко́ль')],0)
word('il-faut','fr:il-faut:necessary-action','il faut','нужно выполнить действие (учебная рамка)','иль фо́',4,ex('Il faut demander de l’aide.','Нужно попросить помощи.','иль фо дёма(н)дэ дё лэ́д'),['Нужно выполнить действие','Я не могу прийти','Я согласен'],0,'Нужно понять указание об ожидании в учебной сценке очереди.',[('Avec plaisir.','авэк плэзи́р'),('Il faut attendre.','иль фо ата́(н)др'),('Je ne peux pas.','жё нё пё па́')],1)
word('demander','fr:demander:ask-for','demander','просить, спрашивать (в показанной рамке)','дёма(н)дэ́',4,ex('Je voudrais demander de l’aide.','Я хотел бы попросить помощи.','жё вудрэ дёма(н)дэ дё лэ́д'),['Продавать','Спать','Просить, спрашивать'],2,'Нужно сказать, что вы хотите попросить помощи.',[('Je voudrais demander de l’aide.','жё вудрэ дёма(н)дэ дё лэ́д'),('Je vends des livres.','жё ва(н) дэ ли́вр'),('Je suis fatigué.','жё сюи фатигэ́')],0)
word('aide','fr:aide:assistance','de l’aide','помощь (в просьбе о помощи)','дё лэ́д',4,ex('Je voudrais de l’aide.','Я хотел бы помощи.','жё вудрэ дё лэ́д'),['Вода','Ключ','Помощь'],2,'Нужна просьба о помощи, а не о воде или ключе.',[('Je voudrais de l’eau.','жё вудрэ дё ло́'),('Je voudrais de l’aide.','жё вудрэ дё лэ́д'),('La clé, s’il vous plaît.','ла клэ, силь ву плэ́')],1)
