intro(s,2,'J’ai mal — «у меня болит». Место называют после à: J’ai mal à la tête. J’ai mal à la gorge. Для двух других выбранных названий: J’ai mal au dos. J’ai mal au ventre. Это готовые сочетания голова, горло, спина и живот. Au объединяет предлог и артикль мужского рода. Фразы сообщают ощущение говорящего; по ним в этих заданиях не определяют болезнь или способ лечения.',['jai-mal'],[('J’ai mal','жэ маль'),('à','а'),('J’ai mal à la tête.','жэ маль а ла тэ́т'),('J’ai mal à la gorge.','жэ маль а ла го́рж'),('J’ai mal au dos.','жэ маль о до́'),('J’ai mal au ventre.','жэ маль о ва́(н)тр'),('Au','о')],('J’ai mal à la tête. J’ai mal au dos. J’ai mal au ventre. J’ai mal à la gorge.','жэ маль а ла тэ́т. жэ маль о до́. жэ маль о ва́(н)тр. жэ маль а ла го́рж.'))
phrase_pairs(s,[U],[('J’ai mal à la tête.','жэ маль а ла тэ́т','У меня болит голова.',['jai-mal','tete'],['jai-mal','tete']),('J’ai mal au dos.','жэ маль о до́','У меня болит спина.',['jai-mal','dos'],['dos']),('J’ai mal au ventre.','жэ маль о ва́(н)тр','У меня болит живот.',['jai-mal','ventre'],['ventre'])],'Вы различили три сообщения о месте боли.','Форма сообщения одна, но названная часть тела различается. Сохраните именно её.')
listen(s,[U],['bonjour','jai-mal','dos','et','ventre','oui','merci'],['dos','ventre'],'В первой и третьей репликах говорит посетитель, во второй собеседник уточняет. Какие две части тела назвал посетитель?','— Bonjour. J’ai mal au dos et au ventre. — Au dos et au ventre ? — Oui. Merci.','— бо(н)жу́р. жэ маль о до э о ва́(н)тр. — о до э о ва́(н)тр? — уи́. мэрси́.',['Спина и живот','Голова и живот','Голова и горло'],0,'Посетитель называет спину и живот.','Уточнение повторяет эти же две части тела. Голова и горло не названы.')
choose(s,'vocabulary',[U],['jai-mal','gorge','tete','ventre'],['gorge'],'Нужно сказать «У меня болит горло». Что выбрать?',ru('Сохраните названную часть тела.'),[fr('J’ai mal à la tête.','жэ маль а ла тэ́т'),fr('J’ai mal à la gorge.','жэ маль а ла го́рж'),fr('J’ai mal au ventre.','жэ маль о ва́(н)тр')],1,'Реплика сообщает о боли в горле.','Голова и живот меняют место боли; нужно прямо назвать горло.')
choose(s,'reading',[U],['bonjour','jai-mal','tete','et','gorge','pharmacie','pres-de','gare','merci'],['tete','gorge'],'Какие две части тела названы в сообщении о боли?',fr('Bonjour. J’ai mal à la tête et à la gorge. La pharmacie est près de la gare. Merci.','бо(н)жу́р. жэ маль а ла тэт э а ла го́рж. ла фармаси э прэ дё ла га́р. мэрси́.'),['Спина и живот','Голова и живот','Голова и горло'],2,'Названы голова и горло.','Расположение аптеки не задаёт место боли. В сообщении о боли прямо названы голова и горло.')
grammar(fill(s,[U],['jai-mal','dos'],[],'Восстановите показанное сочетание перед названием спины.','J’ai mal ','жэ ма́ль',' dos.','до́',[fr('au','о'),fr('à la','а ла')],0,'J’ai mal au dos.','жэ маль о до́.','Сохранено сочетание с названием спины.','В изученном образце перед спиной используется объединённая форма, а не сочетание женского рода.'))
order(s,[U],['bonjour','jai-mal','tete','et','gorge'],[],'Соберите «Здравствуйте. У меня болят голова и горло». Начните с приветствия, затем сообщение с этими частями тела.',[('Bonjour.','бо(н)жу́р'),('J’ai mal','жэ ма́ль'),('à la tête','а ла тэ́т'),('et à la gorge.','э а ла го́рж')],'Bonjour. J’ai mal à la tête et à la gorge.','бо(н)жу́р. жэ маль а ла тэт э а ла го́рж.','Получилось короткое сообщение с двумя названными частями тела.','Сначала поставьте приветствие, затем у меня болит, голову и горло в указанном порядке.')
page(s,[('Сообщить место боли',['Готовая рамка сообщает собственное ощущение. Ответ в задании зависит от названной части тела, а не от предполагаемой причины.'],[W['jai-mal']['example']]),('Выбранные сочетания',['С головой и горлом показано одно сочетание, со спиной и животом — другое. Полный перечень частей тела и исключений здесь не вводится.'],[ex('J’ai mal au dos. J’ai mal au ventre.','У меня болит спина. У меня болит живот.','жэ маль о до́. жэ маль о ва́(н)тр.')]),('Понять реплику',['Уточняющий вопрос может повторить названные слова. Роли говорящих заданы в условии; признаки голоса не нужны для ответа.'],[ex('J’ai mal à la gorge.','У меня болит горло.','жэ маль а ла го́рж')])])

