order(s,[A],['se-sentir','fatigue','je-ne-peux-pas','aller','cinema','midi'],[],'Соберите сообщение «Я чувствую себя уставшим. Я не могу пойти в кино в полдень». Сначала самочувствие, затем невозможность принять приглашение.',[('Je me sens','жё мё са́(н)'),('fatigué.','фатигэ́'),('Je ne peux pas','жё нё пё па́'),('aller au cinéma','алэ о синэма́'),('à midi.','а миди́')],'Je me sens fatigué. Je ne peux pas aller au cinéma à midi.','жё мё са(н) фатигэ́. жё нё пё па алэ о синэма а миди́.','Получились самоописание и ответ на приглашение.','Сначала поставьте чувствую себя уставшим, затем не могу пойти в кино и полдень.')
page(s,[('Самоописание',['Уставший и болен — разные слова в сообщении говорящего. В этой практике нужно распознать прямо названное, не устанавливать причину или диагноз.'],[W['fatigue']['example'],W['malade']['example']]),('Чувствовать себя',['Показана готовая личная форма знакомого способа описывать себя. В ней сохраняется форма о себе, без полной таблицы спряжения.'],[W['se-sentir']['example']]),('Чьи сведения',['В тексте о двух людях самочувствие одного не переносится на другого. Общие знакомые ответы о самочувствии также сохраняют свои прежние значения.'],[W['ca-va-bien']['example'],W['pas-tres-bien']['example']])])

